<?php require __DIR__ . '/partials/header.php'; ?>
<main><section class="website-public-section"><h1><?= e($sections['teachers_title'] ?? 'Our Teachers') ?></h1><div class="website-public-teachers"><?php foreach ($teachers as $teacher): ?><article><?php if (!empty($teacher['photo_path'])): ?><img src="<?= e(public_upload_url($teacher['photo_path'])) ?>" alt="<?= e($teacher['full_name']) ?>"><?php else: ?><span class="website-review-avatar"><?= e(strtoupper(substr($teacher['full_name'], 0, 2))) ?></span><?php endif; ?><h3><?= e($teacher['full_name']) ?></h3><span><?= e($teacher['role_title']) ?> <?= $teacher['subject'] ? '| ' . e($teacher['subject']) : '' ?></span><p><?= e($teacher['biography']) ?></p><?php if (!empty($websiteSettings['show_teacher_email']) && !empty($teacher['email'])): ?><a href="mailto:<?= e($teacher['email']) ?>"><?= e($teacher['email']) ?></a><?php endif; ?><?php if (!empty($websiteSettings['show_teacher_phone']) && !empty($teacher['phone'])): ?><a href="tel:<?= e($teacher['phone']) ?>"><?= e($teacher['phone']) ?></a><?php endif; ?></article><?php endforeach; ?><?php if (empty($teachers)): ?><p>Our teachers will be displayed here soon.</p><?php endif; ?></div></section></main>
